//! What a rejected selector says, and where it says it.
//!
//! This module is the product, not the plumbing. A selector is written by a
//! person at a shell or generated by a model, and in both cases the only way the
//! next attempt is better than the last is if the rejection said what to write
//! instead. So an error here carries three things — what was found, exactly
//! where, and the fix — and renders them in the shape of a compiler diagnostic,
//! which is the shape both audiences already read:
//!
//! ```text
//! `.primary` is a CSS class, and an accessibility tree has no classes
//!
//!   button.primary
//!         ^^^^^^^^
//!
//!   help: match the accessible name instead: button[name="…"]
//! ```
//!
//! Two rules hold for every variant of [`ErrorKind`], and both are checked over
//! generated input in `tests/errors.rs` rather than left as intentions:
//!
//! - **Every rejection names a fix.** [`ErrorKind::help`] is never empty. A
//!   diagnostic that only says "no" leaves the caller to guess, and a model to
//!   guess repeatedly.
//! - **Every rejection points somewhere real.** The span lies inside the input
//!   and on character boundaries, so the caret sits under the offending text
//!   rather than near it.
//!
//! The variants are many and narrow on purpose. `.class`, `#id`, `::before`,
//! `+`, `,` and `:nth-child(2)` are all "not supported", and collapsing them
//! into one syntax error would be true and useless — each has a *different*
//! right answer here, and naming which one was written is what turns a rejection
//! into a correction.

use std::fmt;
use std::ops::Range;

use waypuppet_proto::{Failure, MatchOp};

use crate::roles;

/// A selector that could not be parsed, and everything needed to explain it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParseError {
    /// The selector as it was written.
    pub input: String,
    /// Byte range of the offending text within [`ParseError::input`]. May be
    /// empty, for something missing rather than something wrong.
    pub span: Range<usize>,
    /// What went wrong.
    pub kind: ErrorKind,
}

impl ParseError {
    /// The offending text itself.
    #[must_use]
    pub fn found(&self) -> &str {
        self.input.get(self.span.clone()).unwrap_or_default()
    }
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let (echoed, caret_at, caret_len) = echo(&self.input, &self.span);
        write!(
            f,
            "{}\n\n  {}\n  {}{}\n\n  help: {}",
            self.kind.message(),
            echoed,
            " ".repeat(caret_at),
            "^".repeat(caret_len),
            self.kind.help(),
        )
    }
}

impl std::error::Error for ParseError {}

impl From<ParseError> for Failure {
    /// A parse error crosses the wire as [`Failure::BadQuery`] carrying the
    /// whole rendered diagnostic — caret, help and all — rather than a summary.
    /// The caller who needs it is the one who wrote the selector, and there is
    /// no second chance to ask for the detail.
    fn from(error: ParseError) -> Self {
        Failure::BadQuery(error.to_string())
    }
}

/// Which way a selector was wrong.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ErrorKind {
    /// There was no selector at all.
    Empty,
    /// A type selector named something that is not an AT-SPI role.
    UnknownRole {
        /// The role as it was written.
        written: String,
        /// Real roles closest to it, possibly empty. See [`roles::suggest`].
        suggestions: Vec<&'static str>,
    },
    /// A role written with the spaces AT-SPI puts in it — `list item` — which
    /// the grammar reads as two steps because a space is the descendant axis.
    SpacedRole {
        /// The whole run of words, as written.
        written: String,
        /// The role they spell.
        role: &'static str,
    },
    /// A `[role…]` matcher no real role can satisfy.
    UnsatisfiableRole {
        /// How the comparison was spelled.
        op: MatchOp,
        /// What it compared against.
        value: String,
    },
    /// An attribute selector named something a node does not have.
    UnknownAttribute {
        /// The attribute as it was written.
        written: String,
    },
    /// One step constrained the same attribute twice.
    RepeatedAttribute {
        /// The attribute as it was written.
        written: String,
    },
    /// A CSS class selector — `.primary`.
    Class {
        /// The class name, without the dot.
        written: String,
    },
    /// A CSS id selector — `#save`.
    Id {
        /// The id, without the hash.
        written: String,
    },
    /// A CSS pseudo-element — `::before`.
    PseudoElement {
        /// The name, without the colons.
        written: String,
    },
    /// A pseudo-class other than `:not(…)`.
    PseudoClass {
        /// The name, without the colon and without any argument.
        written: String,
    },
    /// A sibling combinator — `+` or `~`.
    SiblingCombinator {
        /// Which one.
        got: char,
    },
    /// A selector list — `a, b`.
    SelectorList,
    /// A selector that begins with a combinator.
    LeadingCombinator {
        /// Which one.
        got: char,
    },
    /// A combinator with nothing after it.
    DanglingCombinator {
        /// Which one.
        got: char,
    },
    /// Something that reads as `XPath` rather than CSS.
    LooksLikeXPath,
    /// An attribute operator CSS has but waypuppet does not, or one it invents.
    UnsupportedOperator {
        /// The operator as it was written.
        written: String,
    },
    /// An attribute comparison with nothing to compare against — `[name=]`.
    ExpectedValue,
    /// A quoted value with no closing quote.
    UnterminatedString {
        /// Which quote opened it.
        quote: char,
    },
    /// A bracket or parenthesis that was never closed.
    Unclosed {
        /// Which one opened it.
        open: char,
    },
    /// A flag after an attribute value that is not `i`.
    BadCaseFlag {
        /// The flag as it was written.
        written: String,
    },
    /// A step that constrains nothing — an empty `[]`, or a stray qualifier
    /// with no compound to attach to.
    EmptyStep,
    /// Anything else: a character with no meaning where it appeared.
    Unexpected {
        /// The character found.
        got: char,
    },
}

impl ErrorKind {
    /// What went wrong, as a sentence.
    #[must_use]
    pub fn message(&self) -> String {
        match self {
            ErrorKind::Empty => "a selector has to name something".to_owned(),
            ErrorKind::UnknownRole { written, .. } => {
                format!("`{written}` is not an AT-SPI role")
            }
            ErrorKind::SpacedRole { written, .. } => {
                format!("`{written}` reads as two steps, because a space means \"descendant of\"")
            }
            ErrorKind::UnsatisfiableRole { op, value } => {
                format!("no AT-SPI role {} `{value}`", phrase(*op))
            }
            ErrorKind::UnknownAttribute { written } => {
                format!("a node has no `{written}`")
            }
            ErrorKind::RepeatedAttribute { written } => {
                format!("this step already says what `{written}` has to be")
            }
            ErrorKind::Class { written } => {
                format!("`.{written}` is a CSS class, and an accessibility tree has no classes")
            }
            ErrorKind::Id { written } => {
                format!("`#{written}` is a CSS id, and waypuppet does not read node ids yet")
            }
            ErrorKind::PseudoElement { written } => {
                format!("`::{written}` is a pseudo-element, and there is nothing here to style")
            }
            ErrorKind::PseudoClass { written } => {
                format!("`:{written}` is not a pseudo-class waypuppet knows")
            }
            ErrorKind::SiblingCombinator { got } => {
                format!("`{got}` selects a sibling, which waypuppet cannot do yet")
            }
            ErrorKind::SelectorList => {
                "`,` joins two selectors, and this has to name exactly one node".to_owned()
            }
            ErrorKind::LeadingCombinator { got } => {
                format!("a selector cannot begin with `{got}`")
            }
            ErrorKind::DanglingCombinator { got } => {
                format!("`{got}` needs something after it")
            }
            ErrorKind::LooksLikeXPath => "this reads as XPath, not as a CSS selector".to_owned(),
            ErrorKind::UnsupportedOperator { written } => {
                format!("`{written}` is not an operator waypuppet knows")
            }
            ErrorKind::ExpectedValue => "there is nothing to compare against".to_owned(),
            ErrorKind::UnterminatedString { quote } => {
                format!("this {quote} was never closed")
            }
            ErrorKind::Unclosed { open } => format!("this `{open}` was never closed"),
            ErrorKind::BadCaseFlag { written } => {
                format!("`{written}` is not a flag an attribute takes")
            }
            ErrorKind::EmptyStep => "this step constrains nothing".to_owned(),
            ErrorKind::Unexpected { got } => format!("`{got}` has no meaning here"),
        }
    }

    /// What to write instead. Never empty — a rejection without a fix is half a
    /// diagnostic, and the half that does not help.
    #[must_use]
    pub fn help(&self) -> String {
        match self {
            ErrorKind::Empty => {
                "name a role, a name, or both: `button`, `[name=\"Save\"]`, `button[name=\"Save\"]`"
                    .to_owned()
            }
            ErrorKind::UnknownRole {
                written,
                suggestions,
            } => suggestion_help(written, suggestions),
            ErrorKind::SpacedRole { role, .. } => {
                // The one place CSS's syntax and AT-SPI's vocabulary collide,
                // so it is the one mistake worth spending a whole variant on:
                // without this the caller is told `item` is not a role and
                // offered `icon`, which is true, useless, and points away from
                // the answer they are standing on.
                format!(
                    "write the role with hyphens: `{}`",
                    role.replace(' ', "-")
                )
            }
            ErrorKind::UnsatisfiableRole { .. } => {
                "role names are lower case and space-separated — `list item`, `push button menu`; \
                 write spaces as hyphens in a type selector (`list-item`)"
                    .to_owned()
            }
            ErrorKind::UnknownAttribute { written } => {
                let mut help =
                    "the attributes a node has are `role` and `name`".to_owned();
                if matches!(written.as_str(), "text" | "label" | "title" | "value" | "content") {
                    help.push_str(
                        "; the visible words of a widget are its `name`, so `[name=\"…\"]`",
                    );
                }
                help
            }
            ErrorKind::RepeatedAttribute { written } => {
                // CSS means "both must hold" here, and a `Predicate` holds one
                // matcher per attribute. Keeping only the last would answer a
                // question the caller did not ask, so it is refused instead.
                format!(
                    "a step says what each attribute has to be once; for two conditions on \
                     `{written}`, use the one that covers both — `*=` matches part of a value"
                )
            }
            ErrorKind::Class { .. } => {
                "match the accessible name instead: `[name=\"…\"]`, or `[name*=\"…\"]` for part of it"
                    .to_owned()
            }
            ErrorKind::Id { .. } => {
                "match the role and name instead: `button[name=\"Save\"]`; \
                 run `waypuppet tree` to see what an application publishes"
                    .to_owned()
            }
            ErrorKind::PseudoElement { .. } => {
                "select the widget itself: `button[name=\"Save\"]`".to_owned()
            }
            ErrorKind::PseudoClass { written } => pseudo_class_help(written),
            ErrorKind::SiblingCombinator { .. } => {
                "narrow by ancestor instead — `dialog button` for a descendant, `dialog > button` \
                 for a direct child — or pick between matches with `--index`"
                    .to_owned()
            }
            ErrorKind::SelectorList => {
                "write one selector; if several nodes legitimately match, choose with `--index N`"
                    .to_owned()
            }
            ErrorKind::LeadingCombinator { .. } => {
                "the first step matches anywhere in the tree, so start with what you want: \
                 `dialog > button`"
                    .to_owned()
            }
            ErrorKind::DanglingCombinator { .. } => {
                "say what the child has to be: `dialog > button`".to_owned()
            }
            ErrorKind::LooksLikeXPath => {
                "waypuppet takes CSS selectors: `//button[@name='Save']` is `button[name=\"Save\"]`, \
                 and `/dialog/button` is `dialog > button`"
                    .to_owned()
            }
            ErrorKind::UnsupportedOperator { written } => operator_help(written),
            ErrorKind::ExpectedValue => {
                "give it a value: `[name=\"Save\"]`, or drop the operator to ask only that the \
                 attribute is there: `[name]`"
                    .to_owned()
            }
            ErrorKind::UnterminatedString { quote } => {
                format!("close it: `[name={quote}Save{quote}]`")
            }
            ErrorKind::Unclosed { open } => {
                let closed = if *open == '[' { "[name=\"Save\"]" } else { ":not([name=\"Save\"])" };
                format!("close it: `{closed}`")
            }
            ErrorKind::BadCaseFlag { .. } => {
                "the only flag is `i`, which folds case: `[name=\"save\" i]`".to_owned()
            }
            ErrorKind::EmptyStep => {
                "give the step something to match: a role (`button`), an attribute \
                 (`[name=\"Save\"]`), or `*` for any node"
                    .to_owned()
            }
            ErrorKind::Unexpected { .. } => {
                "a selector is a role, attributes in brackets, and steps separated by a space or \
                 `>`: `dialog > button[name*=\"Save\"]`"
                    .to_owned()
            }
        }
    }
}

/// The help for an unknown role: the closest real ones if there are any, and
/// otherwise a pointer at the tree the application actually published, which is
/// the only place the answer can come from.
fn suggestion_help(written: &str, suggestions: &[&'static str]) -> String {
    if suggestions.is_empty() {
        return format!(
            "AT-SPI roles are not HTML tags — there is no `{written}`; \
             run `waypuppet tree` to see the roles this application publishes"
        );
    }
    let named = suggestions
        .iter()
        .map(|role| format!("`{}`", role.replace(' ', "-")))
        .collect::<Vec<_>>()
        .join(" or ");
    format!("did you mean {named}?")
}

/// The help for a pseudo-class. The named cases are the ones a model reaches
/// for, and each has a different right answer — which is the whole reason these
/// are not one "unsupported pseudo-class" message.
fn pseudo_class_help(written: &str) -> String {
    match written {
        "checked" | "disabled" | "enabled" | "focus" | "focus-visible" | "focused" | "selected"
        | "indeterminate" => {
            "waypuppet does not publish AT-SPI states in the tree yet, so a widget cannot be \
             selected by whether it is checked or enabled; select it by role and name and check \
             the result in a capture"
                .to_owned()
        }
        "hover" | "active" | "visited" | "link" => {
            "these describe a live pointer or browsing state, which an accessibility tree does \
             not carry; select by role and name"
                .to_owned()
        }
        "nth-child" | "nth-of-type" | "first-child" | "last-child" | "first-of-type"
        | "last-of-type" | "only-child" | "nth-last-child" => {
            "position is not part of the selector: pick between matches with `--index N`, which \
             is zero-based and counts every match of the whole selector in tree order"
                .to_owned()
        }
        "contains" => "match part of the name with `[name*=\"…\"]`".to_owned(),
        "has" => {
            "selecting a node by its descendants is not supported; select the descendant itself, \
             or narrow with an ancestor step: `dialog button`"
                .to_owned()
        }
        "root" => "the root is matched by its role, usually `application`".to_owned(),
        "empty" | "not-empty" => {
            "ask about the name instead: `[name]` matches a node that has one".to_owned()
        }
        _ => "the only pseudo-class waypuppet knows is `:not(…)`".to_owned(),
    }
}

/// The help for an operator. `~=` and `|=` are the interesting ones: they are
/// real CSS with real meanings that are wrong here, so the message says what
/// they mean rather than only that they are refused.
fn operator_help(written: &str) -> String {
    match written {
        "~=" => "CSS's `~=` matches one word of a space-separated list, which is not what an \
             accessible name is; use `*=` for part of the name"
            .to_owned(),
        "|=" => "CSS's `|=` matches a hyphen-separated language subtag; use `^=` for the start of \
             the name"
            .to_owned(),
        "=~" | "~" => {
            "there is no regular-expression operator: `*=` matches part of a name, `^=` its \
             start, `$=` its end"
                .to_owned()
        }
        _ => "the operators are `=` (whole), `*=` (part), `^=` (start) and `$=` (end), \
             optionally followed by `i` to fold case"
            .to_owned(),
    }
}

/// How to say a [`MatchOp`] in a sentence about roles.
fn phrase(op: MatchOp) -> &'static str {
    match op {
        MatchOp::Exact => "is",
        MatchOp::Contains => "contains",
        MatchOp::Prefix => "starts with",
        MatchOp::Suffix => "ends with",
    }
}

/// Render the input for the caret line, escaping anything that would break it,
/// and translate the byte span into a column and width over that rendering.
///
/// Control characters are escaped rather than printed because a selector
/// carrying a newline would otherwise put the caret under the wrong line — and a
/// diagnostic that points at the wrong place is worse than one that does not
/// point at all.
fn echo(input: &str, span: &Range<usize>) -> (String, usize, usize) {
    let mut echoed = String::with_capacity(input.len());
    let mut before = 0usize;
    let mut within = 0usize;

    for (at, ch) in input.char_indices() {
        let rendered: String = if ch.is_control() {
            ch.escape_debug().collect()
        } else {
            ch.to_string()
        };
        let width = rendered.chars().count();
        if at < span.start {
            before += width;
        } else if at < span.end {
            within += width;
        }
        echoed.push_str(&rendered);
    }

    // An empty span means something was missing rather than wrong — at the end
    // of the input, usually — so the caret still gets somewhere to sit.
    (echoed, before, within.max(1))
}

/// Build the [`ErrorKind::UnknownRole`] for a role token, suggestions included.
pub(crate) fn unknown_role(written: &str) -> ErrorKind {
    ErrorKind::UnknownRole {
        written: written.to_owned(),
        suggestions: roles::suggest(written),
    }
}

#[cfg(test)]
mod tests {
    use super::{ErrorKind, ParseError, echo};

    #[test]
    fn the_diagnostic_points_under_the_offending_text() {
        let error = ParseError {
            input: "button.primary".to_owned(),
            span: 6..14,
            kind: ErrorKind::Class {
                written: "primary".to_owned(),
            },
        };
        let rendered = error.to_string();
        let lines: Vec<&str> = rendered.lines().collect();

        // The echoed input, then a caret line whose carets start under the dot.
        let echoed = lines
            .iter()
            .position(|l| l.trim() == "button.primary")
            .unwrap();
        let carets = lines[echoed + 1];
        assert_eq!(carets, "        ^^^^^^^^");
        assert_eq!(error.found(), ".primary");
    }

    #[test]
    fn a_control_character_does_not_derail_the_caret() {
        // A selector with a newline in it would otherwise print a caret line
        // under the wrong row entirely.
        let (echoed, at, len) = echo("a\nb", &(2..3));
        assert_eq!(echoed, "a\\nb");
        assert_eq!(&echoed[at..at + len], "b");
    }

    #[test]
    fn an_empty_span_still_gets_a_caret() {
        let (_, _, len) = echo("button >", &(8..8));
        assert_eq!(len, 1);
    }
}
